def eprint(s=""):
    sys.stderr.write(str(s) + "\n")

def parse_error(msg, usage=True, version_usage=False, tip=None):
    eprint(msg)
    if tip:
        eprint("")
        eprint(tip)
    if usage:
        eprint("")
        if version_usage:
            eprint("Usage: executable --version [ARGS]...")
        else:
            eprint("Usage: executable [OPTIONS] [ARGS]...")
    eprint("")
    eprint("For more information, try '--help'.")
    return 2

def missing_value(opt_display):
    return parse_error(f"error: a value is required for '{opt_display}' but none was supplied", usage=False)

def duplicate(opt_display):
    return parse_error(f"error: the argument '{opt_display}' cannot be used multiple times")

def unknown_arg(arg, version_usage=False):
    return parse_error(f"error: unexpected argument '{arg}' found", tip=f"  tip: to pass '{arg}' as a value, use '-- {arg}'", version_usage=version_usage)

def normalize(lang):
    if lang is None: return None
    return ALIASES.get(lang.lower())

def unknown_language(lang):
    eprint(f"Error: Unknown language '{lang}'. Available languages: {AVAILABLE}")
    return 1

def run_subprocess(args, cwd=None, input_data=None):
    try:
        p = subprocess.run(args, cwd=cwd, input=input_data, text=True)
        return p.returncode
    except FileNotFoundError:
        eprint("Error: No such file or directory (os error 2)")
        return 1

def is_path_like_for_lang(s, lang):
    if os.path.exists(s):
        return True
    if '/' in s or '\\' in s:
        return True
    ext = ''.join(Path(s).suffixes[-1:])
    if lang == 'python' and ext in ('.py','.pyw'):
        return True
    if lang == 'javascript' and ext in ('.js','.mjs'):
        return True
    if lang == 'typescript' and ext == '.ts':
        return True
    if lang == 'ruby' and ext == '.rb': return True
    if lang == 'go' and ext == '.go': return True
    if lang == 'rust' and ext == '.rs': return True
    if lang == 'c' and ext == '.c': return True
    if lang == 'cpp' and ext in ('.cpp','.cc','.cxx','.hpp'): return True
    if lang == 'perl' and ext == '.pl': return True
    if lang == 'bash' and ext in ('.sh','.bash'): return True
    return False

def detect_code(code):
    s = code.lstrip()
    low = s.lower()
    if s.startswith('#!'):
        first = s.split('\n',1)[0]
        if 'python' in first: return 'python'
        if 'bash' in first or '/sh' in first: return 'bash'
        if 'perl' in first: return 'perl'
        if 'ruby' in first: return 'ruby'
    if low.startswith('<?php') or '<?php' in low[:20]: return 'php'
    if 'package main' in s and 'func main' in s: return 'go'
    if s.startswith('fn main') or 'fn main' in s[:80] or 'println!' in s: return 'rust'
    if s.startswith('#include'):
        if '<iostream>' in s or 'std::' in s or '.hpp' in s:
            return 'cpp'
        return 'c'
    if 'console.log' in s or low.startswith('function '): return 'javascript'
    if low.startswith('echo ') or low.startswith('cd ') or low.startswith('ls '): return 'bash'
    if low.startswith('puts ') or low.startswith('require '): return 'ruby'
    if low.startswith('use strict') or low.startswith('my '): return 'perl'
    if low.startswith('let '): return 'haskell'
    if s.startswith('println('): return 'julia'
    if low.startswith('import ') or low.startswith('from ') or low.startswith('def ') or low.startswith('class ') or ' in range(' in s:
        return 'python'
    if 'print(' in s and ('=' in s or ';' in s or 'sys.' in s or '\n' in s and (s.lstrip().startswith('import') or s.lstrip().startswith('def'))):
        return 'python'
    if s.startswith('print('):
        return 'lua'
    return 'python'

def lang_from_file(path, no_detect=False):
    if no_detect:
        return 'python'
    # pathlib suffix is case-sensitive enough for .R special case
    name = str(path)
    if name.endswith('.R'):
        return 'r'
    ext = Path(name).suffix.lower()
    return EXT_LANG.get(ext, 'python')

def write_and_run_compile(lang, source, is_file=False, file_path=None, stdin_data=None):
    if lang == 'go':
        with tempfile.TemporaryDirectory(prefix='run-go') as td:
            if is_file:
                # go run from the containing directory gives basename-like diagnostics for missing files sometimes
                return run_subprocess(['go','run',file_path], input_data=stdin_data)
            p = os.path.join(td,'main.go')
            open(p,'w').write(source)
            return run_subprocess(['go','run','main.go'], cwd=td, input_data=stdin_data)
    if lang == 'rust':
        with tempfile.TemporaryDirectory(prefix='run-rust') as td:
            src = file_path if is_file else os.path.join(td,'main.rs')
            if not is_file: open(src,'w').write(source)
            out = os.path.join(td,'main')
            code = run_subprocess(['rustc','--crate-name','run_snippet',src,'-o',out])
            if code != 0: return code
            return run_subprocess([out], input_data=stdin_data)
    if lang == 'c':
        with tempfile.TemporaryDirectory(prefix='run-c') as td:
            src = os.path.join(td,'main.c')
            if is_file:
                try: shutil.copyfile(file_path, src)
                except OSError:
                    eprint(f"Error: failed to copy C source from {file_path} to {src}")
                    eprint("")
                    eprint("Caused by:")
                    eprint("    No such file or directory (os error 2)")
                    return 1
            else:
                body = source
                if ('main(' in body) or body.lstrip().startswith('#include'):
                    text = body
                else:
                    text = "#include <stdio.h>\n#include <stdlib.h>\n\nint main(void) {\n    " + body + "\n    return 0;\n}\n"
                open(src,'w').write(text)
            out = os.path.join(td,'main')
            code = run_subprocess(['gcc',src,'-o',out])
            if code != 0: return code
            return run_subprocess([out], input_data=stdin_data)
    if lang == 'cpp':
        with tempfile.TemporaryDirectory(prefix='run-cpp') as td:
            src = os.path.join(td,'main.cpp')
            if is_file:
                try: shutil.copyfile(file_path, src)
                except OSError:
                    eprint(f"Error: failed to copy C++ source from {file_path} to {src}")
                    eprint("")
                    eprint("Caused by:")
                    eprint("    No such file or directory (os error 2)")
                    return 1
            else:
                open(src,'w').write(source)
            out = os.path.join(td,'main')
            code = run_subprocess(['g++',src,'-o',out])
            if code != 0: return code
            return run_subprocess([out], input_data=stdin_data)
    return 1

def execute(lang, code=None, file_path=None, stdin_data=None, mode='inline'):
    canon = normalize(lang) or lang
    if canon is None:
        canon = 'python'
    if canon not in set(ALIASES.values()):
        return unknown_language(lang)
    if canon == 'python':
        py = '/usr/bin/python3' if os.path.exists('/usr/bin/python3') else 'python3'
        if file_path is not None:
            return run_subprocess([py, file_path], input_data=stdin_data)
        return run_subprocess([py, '-c', code or ''], input_data=stdin_data)
    if canon == 'perl':
        if file_path is not None: return run_subprocess(['perl', file_path], input_data=stdin_data)
        return run_subprocess(['perl','-e',code or ''], input_data=stdin_data)
    if canon == 'bash':
        if file_path is not None: return run_subprocess(['/usr/bin/bash' if os.path.exists('/usr/bin/bash') else 'bash', file_path], input_data=stdin_data)
        return run_subprocess(['/usr/bin/bash' if os.path.exists('/usr/bin/bash') else 'bash','-c',code or ''], input_data=stdin_data)
    if canon == 'javascript':
        if file_path is not None: return run_subprocess(['node', file_path], input_data=stdin_data)
        return run_subprocess(['node','-e',code or ''], input_data=stdin_data)
    if canon == 'ruby':
        if file_path is not None: return run_subprocess(['ruby', file_path], input_data=stdin_data)
        return run_subprocess(['ruby','-e',code or ''], input_data=stdin_data)
    if canon == 'typescript':
        if shutil.which('deno') is None:
            kind = 'file execution' if file_path is not None else 'inline execution'
            eprint(f"Error: failed to run Deno for {kind} because 'deno' was not found in PATH. Install Deno from https://deno.land/manual/getting_started/installation or ensure the binary is available on your PATH.")
            return 1
        if file_path is not None: return run_subprocess(['deno','run',file_path], input_data=stdin_data)
        return run_subprocess(['deno','eval',code or ''], input_data=stdin_data)
    if canon in ('go','rust','c','cpp'):
        return write_and_run_compile(canon, code or '', file_path is not None, file_path, stdin_data)
    if canon in MISSING:
        eprint(MISSING[canon])
        return 1
    return unknown_language(lang)

class Parsed:
    def __init__(self):
        self.lang=None; self.file=None; self.code=None; self.no_detect=False; self.args=[]; self.lang_via_option=False; self.code_via_option=False; self.file_via_option=False

def parse(argv):
    p = Parsed()
    i=0; after_dd=False
    # Special command style: leading language makes most following dash words positional,
    # except -c/--code and -f/--file, matching the observed user-facing behavior.
    while i < len(argv):
        a = argv[i]
        if after_dd:
            p.args.append(a); i+=1; continue
        if a == '--':
            after_dd=True; i+=1; continue
        # If first positional is a language, enter loose mode for the rest.
        if p.args and normalize(p.args[0]) and not p.lang_via_option:
            if a in ('--code','-c'):
                if p.code is not None: return duplicate("--code <CODE>")
                if i+1 >= len(argv) or argv[i+1] == '' or argv[i+1].startswith('-'):
                    return missing_value("--code <CODE>")
                p.code = argv[i+1]; p.code_via_option=True; i+=2; continue
            if a in ('--file','-f'):
                if p.file is not None: return duplicate("--file <PATH>")
                if i+1 >= len(argv) or argv[i+1] == '' or argv[i+1].startswith('-'):
                    return missing_value("--file <PATH>")
                p.file = argv[i+1]; p.file_via_option=True; i+=2; continue
            p.args.append(a); i+=1; continue
        if a in ('--help','-h'):
            sys.stdout.write(HELP); return 0
        if a in ('--version','-V'):
            # verify no later unknowns before printing, close to clap
            for rest in argv[i+1:]:
                if rest.startswith('-') and rest not in ('--',):
                    return unknown_arg(rest, version_usage=True)
            sys.stdout.write(VERSION); return 0
        if a == '--no-detect':
            if p.no_detect: return duplicate("--no-detect")
            p.no_detect=True; i+=1; continue
        if a in ('--lang','-l') or (a.startswith('-l') and len(a)>2):
            if p.lang is not None: return duplicate("--lang <LANG>")
            if a.startswith('-l') and a not in ('-l','--lang'):
                val = a[2:]
                if val == '': return missing_value("--lang <LANG>")
                p.lang = val; p.lang_via_option=True; i+=1; continue
            if i+1 >= len(argv) or argv[i+1] == '' or argv[i+1].startswith('-'):
                return missing_value("--lang <LANG>")
            p.lang = argv[i+1]; p.lang_via_option=True; i+=2; continue
        if a in ('--file','-f'):
            if p.file is not None: return duplicate("--file <PATH>")
            if i+1 >= len(argv) or argv[i+1] == '' or argv[i+1].startswith('-'):
                return missing_value("--file <PATH>")
            p.file = argv[i+1]; p.file_via_option=True; i+=2; continue
        if a in ('--code','-c'):
            if p.code is not None: return duplicate("--code <CODE>")
            if i+1 >= len(argv) or argv[i+1] == '' or argv[i+1].startswith('-'):
                return missing_value("--code <CODE>")
            p.code = argv[i+1]; p.code_via_option=True; i+=2; continue
        if a.startswith('-'):
            return unknown_arg(a)
        p.args.append(a); i+=1
    return p

def interactive():
    print("run universal REPL. Type :help for commands.")
    lang='python'
    try:
        while True:
            try: line=input(f"{lang}>>> ")
            except EOFError:
                print("bye"); return 0
            if line in (':exit',':quit'):
                print('bye'); return 0
            if line == ':help':
                print("""Commands:
  :help                 Show this help message
  :languages            List available languages
  :lang <id>            Switch to language <id>
  :detect on|off        Enable or disable auto language detection
  :reset                Reset the current language session
  :load <path>          Execute a file in the current language
  :exit, :quit          Leave the REPL
Any language id or alias works as a shortcut, e.g. :py, :cpp, :csharp, :php.""")
                continue
            if line == ':languages':
                print(AVAILABLE); continue
            if line.startswith(':lang '):
                want=line.split(None,1)[1]
                c=normalize(want)
                if c: lang=c
                else: unknown_language(want)
                continue
            if line.startswith(':load '):
                execute(lang, file_path=line.split(None,1)[1]); continue
            if line.startswith(':'):
                c=normalize(line[1:])
                if c: lang=c; continue
            execute(lang, code=line)
    except KeyboardInterrupt:
        print("bye"); return 0

def main(argv):
    parsed = parse(argv)
    if isinstance(parsed, int):
        return parsed
    p = parsed
    if p.file is not None and p.args:
        eprint("Error: Unexpected positional arguments when --file is present")
        return 1
    if p.code is not None and p.lang_via_option and p.args:
        eprint("Error: Unexpected positional arguments after specifying --code")
        return 1
    # Determine leading positional language
    args = list(p.args)
    if p.lang is None and args and normalize(args[0]):
        p.lang = args.pop(0)
    canon = normalize(p.lang) if p.lang else None
    if p.lang is not None and canon is None:
        return unknown_language(p.lang)
    # stdin handling: only read as program text when no explicit source was supplied
    stdin_payload_for_child = None
    piped_text = None
    stdin_is_tty = sys.stdin.isatty()
    if p.code is None and p.file is None and not args and not stdin_is_tty:
        piped_text = sys.stdin.read()
    # Explicit file flag
    if p.file is not None:
        lang = canon or lang_from_file(p.file, p.no_detect)
        return execute(lang, file_path=p.file)
    # Explicit code flag: extra args after a leading positional language are appended to code
    if p.code is not None:
        code = p.code
        if args and not p.lang_via_option:
            code = ' '.join([code] + args)
        lang = canon or ('python' if p.no_detect else detect_code(code))
        if not stdin_is_tty:
            # for --code, stdin remains data for the subprocess; do not consume it above
            try:
                stdin_payload_for_child = sys.stdin.read()
            except Exception:
                stdin_payload_for_child = None
        return execute(lang, code=code, stdin_data=stdin_payload_for_child)
    # Positional source
    if args:
        if len(args) == 1:
            one = args[0]
            if canon and is_path_like_for_lang(one, canon):
                return execute(canon, file_path=one)
            if not canon and (os.path.exists(one) or '/' in one or '\\' in one):
                lang = lang_from_file(one, p.no_detect)
                return execute(lang, file_path=one)
        code = ' '.join(args)
        lang = canon or ('python' if p.no_detect else detect_code(code))
        return execute(lang, code=code)
    # Piped program text or empty source
    if piped_text is not None:
        if piped_text == '':
            if canon:
                return execute(canon, code='')
            return 0
        lang = canon or ('python' if p.no_detect else detect_code(piped_text))
        return execute(lang, code=piped_text)
    if canon:
        return execute(canon, code='')
    return interactive()

if __name__ == '__main__':
    sys.exit(main(sys.argv[1:]))
